<?php\ndeclare(strict_types=1);\n\ntrait FormFieldTrait\n{\n    protected string $id;\n    protected string $name;\n    protected string $type;\n    protected string $label;\n    protected string $value;\n    protected bool $required;\n    protected int $minLength;\n    protected int $maxLength;\n    protected string $pattern;\n\n    public function render(): string\n    {\n        $html = '<div class="form-group">';\n        $html .= '<label for="' . $this->id . '">' . $this->label . '</label>';\n        $html .= '<input type="' . $this->type . '" name="' . $this->name . '" id="' . $this->id . '"';\n        if ($this->required) { $html .= ' required'; }\n        $html .= ' value="' . htmlspecialchars($this->value) . '"';\n        $html .= ' class="form-control" />';\n        $html .= '</div>';\n        return $html;\n    }\n\n    public function validate(): bool\n    {\n        if ($this->required && empty($this->value)) { return false; }\n        if ($this->minLength && strlen($this->value) < $this->minLength) { return false; }\n        if ($this->maxLength && strlen($this->value) > $this->maxLength) { return false; }\n        if ($this->pattern && !preg_match($this->pattern, $this->value)) { return false; }\n        return true;\n    }\n}\n